C = dict(id='GL-08', title='Drones: Operations and Applications', group='Digital and Technology', level=4,
 summary='Plan and fly safe, legal drone missions for a real purpose such as mapping, inspection or filming, and turn the data into a useful report.',
 outcomes=['Explain how a drone flies, what the main rules are and who is at risk.', 'Run a pre-flight check and fly a planned mission in a simulator or a permitted site.', 'Analyse battery use, wind and image overlap to find why a mission failed or succeeded.', 'Build a mission plan, risk assessment and finished report for one client need.', 'Judge your mission against safety, legal and quality checks.'],
 task='Plan, fly (or simulate) and report one drone mission for a real client need, with a written risk assessment.',
 cond='A drone you may legally fly or a simulator, a permitted open site, a free planning and mapping tool, a spreadsheet, a mentor with flying experience and a peer circle. About 12 weeks part-time.',
 std='Local rules named and followed; written risk assessment signed by the mentor; pre-flight checklist complete; battery plan leaves a 30% reserve; report answers the client question with evidence.',
 who='Surveyors, farmers, estate managers, media learners, safety staff, college learners.', req='None; simulator work is accepted if you cannot fly yet.',
 safety='Fly only where and how your national aviation authority allows. Keep away from people, roads, airports and private property without permission. When unsure, do not fly.',
 mods=[
 ('How a drone flies', 'Understand the four forces and the parts so faults make sense.', ['Lift, weight, thrust and drag; four or more rotors give control by changing speed.', 'Parts: frame, motors, battery, flight controller, sensors, radio link, camera.', 'Positioning by satellite signal; what happens when the signal is lost.', 'Return-to-home and failsafe settings must be checked before every flight.'], 'A drone drifts in a gust. Cause: wind above the stated limit. Action: land, check the forecast, set a 10 m/s stop limit.', 'Label a drone diagram and write what each part does.', 'All main parts labelled; failsafe behaviour explained in own words.'),
 ('Rules, permission and insurance', 'Rules protect people and decide whether you may fly at all.', ['Find your authority\'s registration, pilot knowledge and no-fly rules.', 'Keep away from crowds, airports, prisons, power sites and emergencies.', 'Get written permission from land owners and respect privacy.', 'Check insurance: who pays if something goes wrong?'], 'A client asks for a shot over a school. The plan notes children, privacy and a no-fly zone: decline, offer a safe alternative angle.', 'Write a one-page rules note for your place and get the mentor to check it.', 'Rules note names the authority, limits and permissions required.'),
 ('Risk assessment', 'Risk is chance times harm. Write it down and reduce it before launch.', ['List hazards: people, wind, trees, wires, signal loss, battery failure.', 'Score chance and harm 1 to 5; multiply for a risk score.', 'Add a control for every score of 10 or more.', 'Name who stops the flight and when.'], 'Wires near the site: chance 3, harm 5, score 15. Control: keep 30 m away, spotter watches the wire side, stop if wind passes the limit.', 'Complete a risk assessment for your mission.', 'Every high risk has a control and an owner.'),
 ('Pre-flight and flight skills', 'Checks come before skill. Then practise slow, smooth control.', ['Checklist: weather, battery, propellers, firmware, memory card, radio, return point.', 'Practise take-off, hover, square, figure of eight and landing.', 'Keep line of sight unless your rules allow otherwise.', 'Log every flight: date, place, time, battery, faults.'], 'Battery reads 100% at start; mission needs 18 minutes of a 25-minute flight. Reserve = 7 of 25 minutes = 28%, below 30%; shorten the route.', 'Fly or simulate five practice drills and log them.', 'Five drills logged; checklist used each time.'),
 ('Mission planning and data capture', 'A good plan sets height, overlap and speed to match the question.', ['Choose height: lower gives more detail, covers less.', 'Plan overlap of about 70% front and 60% side for mapping.', 'Plan batteries and landing spots; fly at steady light.', 'Take a few ground reference points for accuracy checks.'], 'A 4-hectare field at 60 m height needs 6 passes and 2 batteries. Time per pass 4 minutes: 24 minutes of flying plus reserve.', 'Write the mission plan with a map and battery table.', 'Plan has height, overlap, passes, batteries and a stop rule.'),
 ('Process and check data', 'Raw pictures are not an answer. Process, check, then explain.', ['Build a map or model with a free tool; check gaps and blur.', 'Compare a measured distance on the ground with the map to find error.', 'Remove people and plates before sharing.', 'Store files with dates and a backup.'], 'A 50 m ground tape reads 49.4 m on the map: error 0.6 m, 1.2%. Report it with the result.', 'Process your pictures and calculate one error figure.', 'Error figure calculated; gaps listed with causes.'),
 ('The client report', 'The report answers the client\'s question in plain words with numbers.', ['Start with the answer, then three supporting findings.', 'Add a map or picture for each finding, with scale and date.', 'State limits: weather, accuracy, areas missed.', 'Give next actions and costs in your own currency.'], 'Report: "Roof has 12 loose tiles on the north side (map 3). Repair estimate EUR 540. Re-inspect in 6 months."', 'Write a two-page report for your mission.', 'Answer first; every claim has a picture or number.'),
 ('Review and next 90 days', 'Reflect on what went wrong and right and plan your growth.', ['Hold a short debrief: what happened, why, what to change.', 'Give two peers written feedback.', 'Share a checklist or template to help the next learner.', 'Plan next 90 days: hours to log, skills to add.'], 'Debrief finds the card filled mid-flight. New rule: format card and check space at the start.', 'Hold the debrief and write the plan.', 'Debrief has at least three changes with dates.')],
 quiz=[('Name the four forces on a drone.', 'Lift, weight, thrust and drag.'), ('What must you check before every flight?', 'Weather, battery, propellers, firmware, memory, radio and return point.'), ('How is a risk score calculated?', 'Chance times harm, each scored 1 to 5.'), ('What battery reserve do we keep?', 'At least 30%.'), ('Why take ground reference points?', 'To check how accurate the map is.'), ('When should you not fly?', 'Near people, airports or banned zones, or when unsure or out of permitted conditions.'), ('What is overlap for?', 'So pictures can be joined into a map.'), ('Why blur people and plates?', 'To protect privacy.'), ('What goes first in a report?', 'The answer to the client question.'), ('Why log every flight?', 'It shows hours, faults and patterns, and supports insurance and safety.')],
 rubric=[('Legal and safe', 'Rules note and risk assessment complete', 'Rules checked with an adviser and controls tested'), ('Flying discipline', 'Checklist and log used every time', 'Log shows improvement and no repeated fault'), ('Mission plan', 'Heights, overlap and batteries correct', 'Plan adjusted for wind and re-tested'), ('Data quality', 'Error figure calculated', 'Gaps explained and fixed'), ('Report', 'Answer first with evidence', 'Client confirms it was useful')],
 jobs=[('Drone operator', 'Flies planned missions for clients'), ('Inspection assistant', 'Checks roofs, lines and structures'), ('Farm or estate mapping assistant', 'Maps fields and sites'), ('Media assistant', 'Films permitted locations safely')],
 next='Nanosatellites and Space Data; Internet of Things; 360-Degree Photography and Virtual Tours.',
 local='Aviation rules differ widely by country and by zone: always read your authority\'s current rules before any flight.',
 evidence='Your evidence: rules note, risk assessment, flight log, mission plan, processed map, error figure, client report and 90-day plan.',
 ladder=[('Basics of flight', 'Explain how a drone flies. Notes: watch a flight, name parts and forces.'), ('Awareness of rules', 'Know registration, no-fly zones and privacy. Notes: read your authority\'s page together.'), ('Safe operator basics', 'Pre-flight, drills and a simple mission. Notes: simulator is acceptable.'), ('Practitioner', 'This course. Notes: full mission with risk assessment and client report.'), ('Specialist mapping or inspection', 'Accuracy checks and standards. Notes: choose mapping, inspection or film.'), ('Advanced operations lead', 'Plan fleets and safety systems. Notes: write operating manuals and train others.'), ('Super expert', 'Set safety method and teach teachers. Notes: review incidents yearly and publish lessons.')])

C['deep'] = dict(mods=[
 ('Thinking the drone is a toy and skipping the failsafe check.', 'Before a flight, the return height is 30 m but a tree is 35 m. Raise the return height to 45 m and test the setting.', 'Name the parts that fail most often and how you check each.'),
 ('Assuming rules are the same as in another country.', 'A visitor flies where a pilot licence is needed locally. The rules note shows the local height limit, checked from the official source, and the registration needed.', 'What are the height and distance limits in your place?'),
 ('Writing "low risk" without a score.', 'People near the site: chance 2, harm 5, score 10, control: cordon and spotter.', 'Which hazard has your highest score, and what is the control?'),
 ('Flying until the battery warning and landing in panic.', 'Rule: land at 30%. With 25 minutes of flight, land at about 17 minutes.', 'What is your land-by time for the mission?'),
 ('Planning one huge flight instead of safe, short ones.', 'Splitting a 6 ha site into two 12-minute flights keeps the reserve above 30% on both.', 'How many batteries does your plan need and why?'),
 ('Trusting the map without a ground check.', 'Map width 52.1 m against 52.0 m measured is 0.2% error; report it.', 'What is the error figure for your map?'),
 ('Burying the answer on page two.', 'Report line one: "Three loose panels on the east roof (map 2); repair estimate 380."', 'Does your first line answer the client question?'),
 ('Skipping the debrief after a good flight.', 'A smooth flight still shows the card was nearly full; add a check step.', 'What one change will you make to your checklist?')],
 gloss=[('Failsafe', 'What the drone does if the signal or battery is lost.'), ('Overlap', 'How much one picture repeats the next so a map can be built.'), ('Line of sight', 'Keeping the drone in view of the pilot.'), ('Ground reference point', 'A marked spot with a known position used to check accuracy.'), ('Reserve', 'Battery kept unused for safety.'), ('Spotter', 'A helper who watches the drone and the area.')],
 cases=[('The crowd', 'A client asks for a sunset shot over a street fair.', 'What is your answer?', 'Decline over the crowd. Offer a shot from a permitted position that keeps people away, after checking rules and getting permission.'),
        ('The wind', 'Forecast gusts rise from 6 to 11 m/s during your slot. Stop limit is 10 m/s.', 'What do you do?', 'Postpone or fly earlier within the limit; log the decision and the forecast.')])
C['deep']['extra'] = [
 ['Learn the sound and feel of each motor; unusual vibration is the earliest warning of a fault.', 'Keep spare propellers and a screwdriver in the kit.'],
 ['Write the emergency contact and the nearest landing site on the checklist.', 'Check whether schools, hospitals or prisons nearby have their own no-fly rules.'],
 ['Re-score the risks when weather changes; a plan is not fixed for the day.', 'Brief every helper in two minutes: what to watch, who can say stop.'],
 ['Practise a manual landing from 10 m with the failsafe off, in a simulator or empty field.', 'Never fly with a puffed or damaged battery; store them in a fire-safe bag.'],
 ['Fly slower for sharper images; blur is a common cause of failed maps.', 'Plan the mission so the sun is behind you where possible, to reduce glare.'],
 ['Keep a copy of raw pictures separate from processed maps.', 'Mark any area with gaps so the client knows what is missing.'],
 ['Use the same scale bar and north arrow on every map in the report.', 'Add a one-line cost per hectare so the client can compare with other methods.'],
 ['Share a near-miss report even if nothing went wrong; patterns show up early.', 'Set a flight-hours target for the next 90 days and log each hour.']]
_np = [['Learn the four forces of lift, weight, thrust and drag, and note that a multirotor holds position only because its controller adjusts motor speeds many times each second.', 'Check battery health before every flight: a pack that sags below 3.5 volts per cell under load, or is puffy, should be retired, because power loss is a leading cause of crashes.'], ['Before a new site, read the current national rules and airspace map, note the current height limit for that place, and save a screenshot of what you checked with the date.', 'Keep a folder with your registration details, pilot proof, insurance document and any site permission, so you can show them quickly if someone asks.'], ['List hazards by category such as people, property, wildlife, weather and radio interference, then give each a likelihood and severity score from 1 to 5 and a control.', 'Set go and no-go limits in advance, for example no flight if wind gusts exceed 8 metres per second or visibility is under 1 kilometre, so the decision is made before pressure builds.'], ['Practise a square, a circle and a slow figure of eight at 10 metres height until each is smooth, then repeat with the nose pointing toward you.', 'Use a printed pre-flight checklist covering props, battery seating, memory card, compass, home point and a short hover at 1 metre before climbing.'], ['For mapping missions choose about 75 percent forward overlap and 65 percent side overlap, and fly at a steady height so the pixel size stays the same across the site.', 'Time flights for even light, ideally midday for mapping or the golden hours for visuals, and avoid shifting cloud that creates patchy exposure across the images.'], ['After processing, check three ground points of known position and compare; an error over twice the pixel size means the control or the settings need another look.', 'Back up the raw images to two places before you start processing, and name folders by date, site and flight number so you can trace any result.'], ["Open with a one-paragraph answer to the client's question, then add a map, two key images, the method in five lines and a note on the accuracy found.", 'State plainly what the data cannot show, such as ground under dense trees, and offer a follow-up flight rather than stretching the claims.'], ['After every five flights, review the log for patterns such as the same checklist item missed or a battery that sags, and write one improvement for the next five.', 'Set three goals for 90 days, for example one new mission type, a documented accuracy check and one client report, and review progress monthly.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
C['intro_add'] = ["You will explain how lift, weight, thrust and drag act on a multirotor, so you can reason about a fault instead of guessing at it.", "You will check current rules, airspace limits and your paperwork before each new site, so you know in advance whether a flight is allowed.", "You will score hazards for likelihood and harm, write controls and set go or no-go limits, so decisions are made calmly before launch.", "You will follow a written pre-flight checklist and fly basic patterns smoothly, building the control habits that keep people and equipment safe.", "You will pick height, overlap and speed to match a client's question, so the pictures you collect can actually answer it.", "You will process images, check results against known ground points and judge accuracy, so your numbers can be trusted before anyone sees them.", "You will write a short client report with a direct answer, a map and honest limits, so the reader can act without needing the raw files.", "You will review your flight log for repeated slips and set measurable goals, turning each flight into practice for the next."]
